package org.circus.core;

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;

/**Actual public COM ABI/lifetime leaves on self-created, never-played buffers.
 *No game EXE/data. Physical graph reconstruction is deliberately not supplied
 *by this probe; a live object cannot acquire a fabricated restoration proof. */
public final class Pc1ComAbiAudit implements AutoCloseable {
    private static int checks;
    private long handle;private final Map<String,String> moduleHashes=new HashMap<>();
    private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
    private interface Work {void run()throws IOException;}
    private static void rejects(Work work,String why)throws IOException{boolean failed=false;try{work.run();}catch(IOException expected){failed=true;}check(failed,why);}
    private Pc1ComAbiAudit(Path dll,long hwnd)throws IOException{System.load(dll.toAbsolutePath().normalize().toString());handle=openNative(hwnd);if(handle==0)throw new IOException("Actual COM probe context missing");}
    private String moduleHash(String path)throws IOException{String found=moduleHashes.get(path);if(found==null){found=Binary.sha256(Files.readAllBytes(Paths.get(path)));moduleHashes.put(path,found);}return found;}
    private final class Physical implements Pc1ComMemory.Binding {
        final Pc1ComAbiAudit backend=Pc1ComAbiAudit.this;final int index;final Pc1ComMemory.Kind kind;final Pc1GuestAddressSpace.ExternalOwner table;final NativeLeaf[] leaves;
        Physical(int index)throws IOException{this.index=index;long[] info=infoNative(handle,index);if(info[0]==0||info[2]==0||info[4]!=0)throw new IOException("Actual COM interface/public vtable module unavailable");kind=index==0?Pc1ComMemory.Kind.DIRECT_SOUND:Pc1ComMemory.Kind.DIRECT_SOUND_BUFFER;String hash=moduleHash(modulePathNative(handle,index,-1));table=new Pc1GuestAddressSpace.ExternalOwner(Pc1ComMemory.VTABLE_OWNER,hash+":"+Long.toHexString(info[1]-info[2])+":"+kind);leaves=new NativeLeaf[Pc1ComMemory.methodCount(kind)];check(info[3]==leaves.length,"Public COM vtable size agrees with SDK interface declaration");for(int n=0;n<leaves.length;n++)leaves[n]=new NativeLeaf(this,n);}
        public Pc1ComMemory.Kind kind(){return kind;}public long physicalIdentity()throws IOException{return infoNative(handle,index)[0];}public boolean live()throws IOException{return handle!=0&&infoNative(handle,index)[0]!=0;}public Pc1GuestAddressSpace.ExternalOwner vtableOwner(){return table;}public Pc1ComMemory.Leaf leaf(int slot){return leaves[slot];}public String contractId(){return "ACTUAL_WINDOWS_COM_ABI_PROBE_V1";}
        public byte[] restorationProof()throws IOException{throw new IOException("Actual COM probe has no physical retained-graph reconstruction owner");}
    }
    private final class NativeLeaf implements Pc1ComMemory.Leaf {
        final Physical source;final Pc1ComMemory.Method method;final Pc1GuestAddressSpace.ExternalOwner owner;final String modulePath,moduleHash;final long functionRva;
        NativeLeaf(Physical source,int slot)throws IOException{this.source=source;method=Pc1ComMemory.method(source.kind,slot);long[] info=leafNative(handle,source.index,slot);if(info[0]==0||info[1]==0||info[2]!=0)throw new IOException("Actual COM function has no verified loaded-module owner");modulePath=modulePathNative(handle,source.index,slot);moduleHash=moduleHash(modulePath);functionRva=info[0]-info[1];/*Explicit32-bit ABI translation distinguishes differing stdcall cleanup
             *contracts, even if a64-bit vendor stub shares machine code.*/owner=new Pc1GuestAddressSpace.ExternalOwner(Pc1ComMemory.CALL_OWNER,moduleHash+":"+Long.toHexString(functionRva)+":w"+method.argumentWords);}
        public Pc1GuestAddressSpace.ExternalOwner owner(){return owner;}public Pc1ComMemory.Method method(){return method;}public String contractId(){return "ACTUAL_WINDOWS_PUBLIC_COM32_TRANSLATION_PROBE_V1";}
        public byte[] restorationProof()throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeUTF(moduleHash);out.writeLong(functionRva);out.writeInt(method.argumentWords);return bytes.toByteArray();}
        public int invoke(Pc1ComMemory.Binding actual,Pc1ComMemory.Stack stack)throws IOException{if(!(actual instanceof Pc1ComAbiAudit.Physical))throw new IOException("Actual COM probe THIS belongs to another physical backend");Physical target=(Physical)actual;if(target.backend!=Pc1ComAbiAudit.this)throw new IOException("Actual COM probe cannot borrow another context's native object index");int value=0;if(method.argumentWords==2)value=stack.word(1);else if(method.argumentWords!=1)throw new IOException("Actual COM probe requires additional raw-pointer/stack marshalling for "+method.name);return invokeNative(handle,source.index,method.slot,target.index,value);}
    }
    private static Pc1ComMemory.Stack stack(final int... words){return index->{if(index<0||index>=words.length)throw new IOException("Unknown probe stack word");return words[index];};}
    private static String hex(ByteBuffer view){StringBuilder out=new StringBuilder();for(int n=0;n<view.capacity();n++)out.append(String.format(Locale.ROOT,"%02x",view.get(n)&255));return out.toString();}
    private static void emitAbi(Path output,Pc1ComMemory com,Pc1GuestAddressSpace space,Physical[] physical,Pc1ComMemory.ObjectRef[] objects)throws IOException{
        StringBuilder json=new StringBuilder("{\"scope\":\"actual public COM ABI translated into this same Guest32 domain; function bodies remain explicit required leaves, not exported code\",\"policy\":\"").append(space.contractIdentity()).append("\",\"objects\":[");Map<Integer,String> regions=new LinkedHashMap<>();Map<Integer,Pc1ComMemory.Leaf> leaves=new LinkedHashMap<>();
        for(int n=0;n<objects.length;n++){Physical binding=physical[n];Pc1ComMemory.ObjectRef object=objects[n];if(n!=0)json.append(',');json.append("{\"address\":").append(object.address).append(",\"owner\":\"").append(object.owner.id).append("\",\"kind\":\"").append(binding.kind).append("\",\"table\":\"").append(binding.table.id).append("\",\"leaves\":[");for(int slot=0;slot<binding.leaves.length;slot++){Pc1ComMemory.Leaf leaf=binding.leaves[slot];if(slot!=0)json.append(',');json.append('"').append(leaf.owner().id).append('"');leaves.put(com.callAddress(leaf.owner()),com.physicalLeaf(leaf.owner()));}json.append("]}");regions.put(object.address,hex(object.borrowedHeader()));regions.put(com.vtableAddress(binding.table),hex(com.borrowedVtable(binding.table)));}
        json.append("],\"regions\":[");int n=0;for(Map.Entry<Integer,String> region:regions.entrySet()){if(n++!=0)json.append(',');json.append("{\"address\":").append(region.getKey()).append(",\"hex\":\"").append(region.getValue()).append("\"}");}json.append("],\"code\":[");n=0;for(Map.Entry<Integer,Pc1ComMemory.Leaf> entry:leaves.entrySet()){if(n++!=0)json.append(',');Pc1ComMemory.Leaf leaf=entry.getValue();json.append("{\"address\":").append(entry.getKey()).append(",\"owner\":\"").append(leaf.owner().id).append("\",\"kind\":\"").append(leaf.method().kind).append("\",\"slot\":").append(leaf.method().slot).append(",\"name\":\"").append(leaf.method().name).append("\",\"words\":").append(leaf.method().argumentWords).append('}');}json.append("]}");Files.write(output,json.toString().getBytes("UTF-8"));
    }
    private static Pc1NativeMemory bus(Pc1GuestAddressSpace space)throws IOException{final byte[] settings=new byte[Pc1NativeSettings.SIZE];Pc1NativeMemory memory=new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int n){return settings[n]&255;}public void write(int n,int value){settings[n]=(byte)value;}});memory.bindGuestAddressSpace(space);return memory;}
    @Override public void close()throws IOException{if(handle!=0){closeNative(handle);handle=0;}}
    public static void main(String[] args)throws Exception{
        if(args.length!=3)throw new IOException("Expected separate COM probe DLL, immutable Window DLL, own stage29 output directory");Path out=Paths.get(args[2]).toAbsolutePath().normalize();if(!out.toString().contains("pc1-com-abi-stage29"))throw new IOException("Probe output must stay in its own evidence directory");Files.createDirectories(out);Pc1WindowsWindow.NativeDispatcher standard=new Pc1WindowsWindow.NativeDispatcher(){public Pc1WindowsWindow.Dispatch dispatch(long hwnd,int message,long w,long l)throws IOException{if(message==0x400||message==0x113||message==0x40d)throw new IOException("No invented engine WndProc consumer in COM probe");return Pc1WindowsWindow.Dispatch.unhandled();}public int quitFlag(){return 0;}};
        try(Pc1WindowsWindow window=new Pc1WindowsWindow(Paths.get(args[1]),standard);Pc1ComAbiAudit probe=new Pc1ComAbiAudit(Paths.get(args[0]),window.hwnd())){
            int[] initialization=initializationNative(probe.handle);check(initialization[0]==0&&initialization[2]==0&&initialization[4]==0&&initialization[5]==0,"Actual DS device, primary and two secondary interfaces created");Pc1GuestAddressSpace space=new Pc1GuestAddressSpace(Pc1GuestAddressSpace.Layout.imageHeapV1());Pc1NativeMemory memory=bus(space);Pc1ComMemory com=new Pc1ComMemory(space);Physical[] physical=new Physical[4];Pc1ComMemory.ObjectRef[] objects=new Pc1ComMemory.ObjectRef[4];
            for(int n=0;n<4;n++){physical[n]=probe.new Physical(n);objects[n]=com.register(new Pc1GuestAddressSpace.ExternalOwner(Pc1ComMemory.INTERFACE_OWNER,"probe-"+n),physical[n]);check(space.readI32(objects[n].address)==com.vtableAddress(physical[n].table),"Actual class publishes a real known guest header/vtable chain");check(objects[n].address!=(int)physical[n].physicalIdentity(),"Actual64 interface is not truncated into raw DWORD");}
            emitAbi(out.resolve("guest-abi-fixture.json"),com,space,physical,objects);long[] primary=infoNative(probe.handle,1),secondary=infoNative(probe.handle,2),other=infoNative(probe.handle,3);check(physical[2].table.equals(physical[3].table)==(secondary[1]==other[1]),"Only actually equal secondary tables are shared");check(physical[1].table.equals(physical[2].table)==(primary[1]==secondary[1]),"Primary/secondary table identity follows actual API, not a hard-coded assumption");
            int cell=Pc1NativeMemory.SETTINGS_BASE+16;space.writeI32(cell,objects[2].address);int table=space.readI32(objects[2].address),volume=com.callAddress(physical[2].leaves[15].owner());int original=space.readI32(table+52);com.borrowedVtable(physical[2].table).putInt(52,volume);Pc1ComMemory.Call redirected=com.resolveCell(cell,52);check(redirected.method.name.equals("SetVolume"),"Guest vtable alias selects actual SetVolume code");check(com.invoke(redirected,stack(objects[2].address,-9000),2)==0,"Selected actual COM leaf executes without Play");int[] actual=volumeNative(probe.handle,2);check(actual[0]==0&&actual[1]==-9000,"Actual DirectSound volume changed through dynamic guest pointer chain");
            int stop=space.readI32(table+72);space.writeI32(table+72,volume);rejects(()->com.invoke(com.resolveCell(cell,72),stack(objects[2].address,-6000),1),"Changed stdcall cleanup remains a precise late boundary");actual=volumeNative(probe.handle,2);check(actual[0]==0&&actual[1]==-6000,"Physical native side effect precedes cleanup boundary");check(com.invoke(redirected,stack(objects[3].address,-8000),2)==0,"A different verified same-class THIS can consume the selected function");int[] target=volumeNative(probe.handle,3);check(target[0]==0&&target[1]==-8000&&volumeNative(probe.handle,2)[1]==-6000,"Actual THIS comes from caller stack rather than a cached function-source object");if(leafNative(probe.handle,2,15)[0]!=leafNative(probe.handle,1,15)[0])rejects(()->com.invoke(redirected,stack(objects[1].address,-7000),2),"Unknown primary/secondary private-layout compatibility is a required leaf");space.writeI32(table+52,original);space.writeI32(table+72,stop);
            int add=com.invoke(com.resolve(objects[2].address,4),stack(objects[2].address),1),one=com.invoke(com.resolve(objects[2].address,8),stack(objects[2].address),1);check(add!=0&&one!=0&&objects[2].live()&&space.contains(objects[2].address),"Actual AddRef/Release nonzero retain same interface header");int last=com.invoke(com.resolve(objects[2].address,8),stack(objects[2].address),1);check(last==0&&!objects[2].live()&&!space.contains(objects[2].address),"Actual zero Release retires guest allocation without surrogate counts");check(space.readI32(cell)==objects[2].address,"Actual release never repairs stale raw engine pointer");rejects(()->com.resolveCell(cell,60),"Released actual interface has no readable fabricated private bytes");rejects(()->com.save(new DataOutputStream(new ByteArrayOutputStream())),"Probe cannot fabricate physical graph restoration proof");
            StringBuilder report=new StringBuilder("{\"scope\":\"self-created hidden HWND; actual DirectSound public ABI and reference/volume leaves; never Play; no game EXE/data; physical graph adoption not implemented by probe\",\"initialization\":").append(Arrays.toString(initialization)).append(",\"primary_vtable_rva\":\"").append(Long.toHexString(primary[1]-primary[2])).append("\",\"secondary_vtable_rva\":\"").append(Long.toHexString(secondary[1]-secondary[2])).append("\",\"addRef\":").append(add&0xffffffffL).append(",\"releaseOne\":").append(one&0xffffffffL).append(",\"releaseZero\":").append(last&0xffffffffL).append(",\"checks\":").append(checks).append('}');Files.write(out.resolve("actual-com-abi.json"),report.toString().getBytes("UTF-8"));com.detachViews();check(space.mappingCount()==0,"Teardown detaches ABI views without extra COM operations");
        }System.out.println("Pc1ComAbiAudit PASS "+checks+"; actual Windows DS COM ABI/volume/AddRef/Release, hidden self-authored window, no Play/game EXE; physical graph restore remains required");
    }
    private static native long openNative(long hwnd)throws IOException;
    private static native int[] initializationNative(long handle)throws IOException;
    private static native long[] infoNative(long handle,int index)throws IOException;
    private static native long[] leafNative(long handle,int index,int slot)throws IOException;
    private static native String modulePathNative(long handle,int index,int slot)throws IOException;
    private static native int invokeNative(long handle,int source,int slot,int target,int value)throws IOException;
    private static native int[] volumeNative(long handle,int index)throws IOException;
    private static native void closeNative(long handle)throws IOException;
}
